    def freeze(v):
        kind=type(v)
        if kind in (str,int,bool,type(None)):return (kind.__name__,v)
        if kind not in (list,tuple,dict):raise ValueError('unsupported key value')
        identity=id(v)
        if identity in active:raise ValueError('cyclic value')
        active.add(identity)
        try:
