                if any(type(k) is not str for k in v):raise ValueError('string mapping keys required')
                result=tuple((k,freeze(v[k])) for k in sorted(v))
            else:result=tuple(freeze(item) for item in v)
            return (kind.__name__,result)
        finally:active.remove(identity)
    return freeze(value)
